package com.dataengine.governance.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="quality_result") public class QualityResult {
 @Id private UUID id; @Column(nullable=false) private UUID changeId; @Column(nullable=false) private UUID ruleId; @Column(nullable=false) private double observedValue; @Column(nullable=false) private double threshold; @Enumerated(EnumType.STRING) @Column(nullable=false) private GateStatus gate; @Enumerated(EnumType.STRING) @Column(nullable=false) private QualityResultStatus status; @Column(nullable=false) private String summary; private String decidedBy; private String decisionReason; @Column(nullable=false) private Instant createdAt; private Instant updatedAt;
 protected QualityResult(){} public QualityResult(UUID changeId,UUID ruleId,double observed,double threshold,GateStatus gate,String summary){id=UUID.randomUUID();this.changeId=changeId;this.ruleId=ruleId;observedValue=observed;this.threshold=threshold;this.gate=gate;this.summary=summary;status=gate==GateStatus.PASS?QualityResultStatus.PASSED:QualityResultStatus.OPEN;createdAt=Instant.now();updatedAt=createdAt;}
 public void decide(QualityResultStatus next,String actor,String reason){status=next;decidedBy=actor;decisionReason=reason;updatedAt=Instant.now();} public UUID getId(){return id;} public UUID getChangeId(){return changeId;} public UUID getRuleId(){return ruleId;} public double getObservedValue(){return observedValue;} public double getThreshold(){return threshold;} public GateStatus getGate(){return gate;} public QualityResultStatus getStatus(){return status;} public String getSummary(){return summary;} public String getDecidedBy(){return decidedBy;} public String getDecisionReason(){return decisionReason;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;}
}
